// Original SVG object studies inspired by the interactive-object concept of Colorfigures.
const base=`.figure-demo{width:min(96%,510px);height:100%;max-height:360px;padding:14px 20px;display:flex;flex-direction:column;justify-content:center;gap:9px;font:11px/1.4 system-ui,sans-serif;color:#e5e5e5}.figure-demo *{box-sizing:border-box}.figure-heading{display:flex;align-items:center;justify-content:space-between;gap:9px}.figure-heading strong{font-size:12px;font-weight:500}.figure-state{color:#999;font-size:9px;border:1px solid #393939;border-radius:4px;padding:3px 6px}.figure-art{display:block;width:100%;height:170px;overflow:visible}.figure-art text{font:9px system-ui,sans-serif;fill:#bbb;stroke:none}.figure-demo .shell{fill:#202020;stroke:#bbb;stroke-width:1.5;stroke-linejoin:round}.figure-demo .side{fill:#131313;stroke:#777;stroke-width:1.2;stroke-linejoin:round}.figure-demo .top{fill:#2e2e2e;stroke:#ccc;stroke-width:1.2;stroke-linejoin:round}.figure-demo .line{fill:none;stroke:#bbb;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}.figure-controls{display:flex;align-items:center;justify-content:center;gap:6px;flex-wrap:wrap}.figure-demo button,.figure-demo input{font:inherit}.figure-demo button{cursor:pointer;padding:6px 9px;background:#222;border:1px solid #444;border-radius:5px;color:#ddd;min-height:28px}.figure-demo button.primary{background:#ddd;border-color:#ddd;color:#111}.figure-demo button:disabled{opacity:.35;cursor:default}.figure-demo button:focus-visible,.figure-demo input:focus-visible{outline:2px solid #ddd;outline-offset:3px}.figure-caption{font-size:9px;color:#888;text-align:center;min-height:13px;margin:0}.figure-settings{display:flex;justify-content:center;gap:14px;font-size:9px;color:#888}.figure-settings label{display:flex;align-items:center;gap:5px}.figure-settings input{accent-color:#ddd}.figure-demo .internals{opacity:0;transition:opacity .2s}.figure-demo.see-through .internals{opacity:1}.figure-demo.see-through .outer-skin{opacity:.24}.figure-demo .part-label{display:none}.figure-demo.labels .part-label{display:block}.figure-art .ground{fill:#ffffff07;stroke:#ffffff12;stroke-width:1}.figure-demo input[type=range]{accent-color:#ddd;max-width:110px}.figure-demo input[type=text]{background:#111;border:1px solid #444;color:#ddd;border-radius:5px;padding:6px 8px;width:90px;min-width:0}@keyframes figure-spin{to{transform:rotate(360deg)}}@keyframes figure-steam{0%{opacity:0;transform:translateY(6px)}50%{opacity:.65}100%{opacity:0;transform:translateY(-15px)}}@media(prefers-reduced-motion:reduce){.figure-demo *{animation:none!important;transition:none!important}}`;
const make=(id,name,description,html,css,js)=>({id,name,category:'figures',description,tags:['Interactive','SVG','Colorfigures'],isNew:true,inspiration:{name:'Colorfigures · April Zhu',url:'https://april-zhu.com/colorfigures',note:'Original SVG and interaction code inspired by playable everyday objects; no source assets imported.'},html,css:base+css,js:js+`;document.querySelector('[data-parts]')?.addEventListener('change',e=>document.querySelector('.figure-demo').classList.toggle('see-through',e.target.checked));document.querySelector('[data-labels]')?.addEventListener('change',e=>document.querySelector('.figure-demo').classList.toggle('labels',e.target.checked));`});
const settings=`<div class="figure-settings"><label><input type="checkbox" data-parts> See inside</label><label><input type="checkbox" data-labels> Labels</label></div>`;
const frame=(title,state,art,controls,caption)=>`<div class="figure-demo"><div class="figure-heading"><strong>${title}</strong><span class="figure-state" id="figure-state">${state}</span></div><svg class="figure-art" viewBox="0 0 340 205" role="img" aria-label="Interactive ${title.toLowerCase()} illustration"><ellipse class="ground" cx="175" cy="184" rx="107" ry="14"/>${art}</svg><div class="figure-controls">${controls}</div>${settings}<p class="figure-caption" id="figure-caption" role="status">${caption}</p></div>`;
export default [
make('ref-washing-machine','Washing machine','Load the drum, start or pause a wash, and inspect the working parts. The door stays locked during a cycle.',
frame('Washing machine','Empty',`<path class="side outer-skin" d="m220 54 31-20v126l-31 20z"/><path class="top outer-skin" d="m100 54 32-20h119l-31 20z"/><rect class="shell outer-skin" x="100" y="54" width="120" height="126" rx="4"/><g class="internals"><path class="line" stroke-dasharray="4 3" d="M108 83h102v87H108z"/><path class="line" d="M114 160h88m-63 7 4 6h42l4-6"/><text x="116" y="79">Drum & motor</text></g><path class="line" d="M101 84h118"/><rect x="111" y="64" width="40" height="11" rx="2" fill="#111" stroke="#777"/><circle cx="204" cy="69" r="6" fill="#888"/><circle cx="160" cy="125" r="35" fill="#111" stroke="#aaa" stroke-width="3"/><g class="washer-drum" style="transform-origin:160px 125px"><circle cx="160" cy="125" r="27" fill="#242424" stroke="#555"/><path class="line laundry" d="m142 119 12-10 12 5 11 17-12 10-16-6z"/><path class="line" stroke="#555" d="m160 98 7 15m17 20-16-2m-23 13 8-16"/></g><path class="washer-door line" d="m184 117 4 1v14l-4 1"/><text class="part-label" x="35" y="126">Drum</text><path class="part-label line" d="M66 123h45"/><text class="part-label" x="253" y="71">Dial</text>`,
`<button id="wash-load">Load</button><button class="primary" id="wash-start" disabled>Start wash</button><button id="wash-reset">Reset</button>`, 'Load the drum to begin.'),
`.washer-drum{animation:figure-spin 1.8s linear infinite;animation-play-state:paused}.washing .washer-drum{animation-play-state:running}.figure-demo:not(.loaded) .laundry{opacity:0}.loaded .laundry{fill:#aaa;stroke:#ddd}.washer-door{transition:transform .2s}.loaded .washer-door{stroke:#eee}`,
`const root=document.querySelector('.figure-demo');let loaded=false,running=false,progress=0,timer;const load=document.querySelector('#wash-load'),start=document.querySelector('#wash-start');function render(){root.classList.toggle('loaded',loaded);root.classList.toggle('washing',running);load.disabled=running||progress>0;load.textContent=loaded?'Unload':'Load';start.disabled=!loaded||progress>=100;start.textContent=running?'Pause':progress?'Resume':'Start wash';document.querySelector('#figure-state').textContent=progress>=100?'Clean':running?'Washing '+progress+'%':loaded?'Loaded':'Empty';document.querySelector('#figure-caption').textContent=progress>=100?'Cycle complete. Reset to wash again.':running?'Door locked while the drum is running.':loaded?'Ready when you are.':'Load the drum to begin.'}load.onclick=()=>{loaded=!loaded;render()};start.onclick=()=>{running=!running;render();clearInterval(timer);if(running)timer=setInterval(()=>{progress=Math.min(100,progress+10);if(progress===100){running=false;clearInterval(timer)}render()},500)};document.querySelector('#wash-reset').onclick=()=>{clearInterval(timer);loaded=running=false;progress=0;render()};render();`),
make('ref-record-player','Record player','Insert a record, lower the tonearm, and change playback speed in a quiet isometric illustration.',
frame('Record player','No record',`<path class="side outer-skin" d="m70 123 184 27 30-19v29l-30 20-184-28z"/><path class="top outer-skin" d="m70 95 31-20 183 27-30 48-184-27z"/><path class="shell outer-skin" d="m70 123 184 27v30L70 152z"/><g class="internals"><ellipse cx="160" cy="121" rx="55" ry="26" fill="none" stroke="#aaa" stroke-dasharray="3 3"/><path class="line" d="m145 145 20 7 18-14"/><text x="190" y="160">Drive motor</text></g><g transform="translate(159 113) scale(1 .44)"><circle r="58" fill="#333" stroke="#ccc"/><g class="record" style="transform-origin:0 0"><circle r="53" fill="#121212" stroke="#777"/><circle r="46" fill="none" stroke="#333"/><circle r="38" fill="none" stroke="#333"/><circle r="29" fill="none" stroke="#333"/><circle r="17" fill="#aaa"/><path d="M-42-25-22-13M26 34l-11-17" stroke="#666" stroke-width="3"/></g><circle r="3" fill="#eee"/></g><g class="tonearm" style="transform-origin:236px 101px"><circle cx="236" cy="101" r="7" fill="#777" stroke="#ddd"/><path class="line" d="m236 101-13 28-20 8"/><rect x="195" y="134" width="12" height="6" rx="2" fill="#ddd"/></g><text x="86" y="147" fill="#aaa">NOIR AUDIO</text><text class="part-label" x="25" y="78">Platter</text><path class="part-label line" d="m63 80 44 17"/><text class="part-label" x="247" y="81">Tonearm</text>`,
`<button id="record-load">Insert record</button><button class="primary" id="record-play" disabled>Play</button><button id="record-speed">33 rpm</button>`, 'Insert a record to enable playback.'),
`.figure-demo:not(.record-loaded) .record{opacity:.12}.record{animation:figure-spin 2.2s linear infinite;animation-play-state:paused}.record-playing .record{animation-play-state:running}.tonearm{transform:rotate(-24deg);transition:transform .4s}.record-playing .tonearm{transform:rotate(0deg)}`,
`let loaded=false,playing=false,fast=false;const root=document.querySelector('.figure-demo'),load=document.querySelector('#record-load'),play=document.querySelector('#record-play');function render(){root.classList.toggle('record-loaded',loaded);root.classList.toggle('record-playing',playing);play.disabled=!loaded;play.textContent=playing?'Pause':'Play';load.disabled=playing;load.textContent=loaded?'Remove record':'Insert record';document.querySelector('#figure-state').textContent=playing?'Playing':loaded?'Ready':'No record';document.querySelector('#figure-caption').textContent=playing?'Visual playback at '+(fast?45:33)+' rpm. No audio is requested.':loaded?'Press Play to lower the tonearm.':'Insert a record to enable playback.';document.querySelector('.record').style.animationDuration=fast?'1.6s':'2.2s';document.querySelector('#record-speed').textContent=(fast?45:33)+' rpm'}load.onclick=()=>{loaded=!loaded;render()};play.onclick=()=>{playing=!playing;render()};document.querySelector('#record-speed').onclick=()=>{fast=!fast;render()};render();`),
make('ref-electric-kettle','Electric kettle','Fill, boil, and pour. Heating requires water, stops at boiling, and exposes a schematic heating element.',
frame('Electric kettle','Empty',`<ellipse cx="165" cy="173" rx="65" ry="15" fill="#222" stroke="#aaa"/><path class="shell outer-skin" d="M116 87q2-23 48-23t48 23l12 67q0 19-60 19t-60-19z"/><ellipse class="top outer-skin" cx="164" cy="87" rx="48" ry="17"/><path class="shell outer-skin" d="m115 99-27-14 14 34 10 1"/><path class="line" stroke-width="8" d="M210 96q39 7 19 48l-11 3"/><path class="line" d="M210 96q39 7 19 48l-11 3"/><rect x="156" y="100" width="17" height="48" rx="7" fill="#111" stroke="#777"/><rect id="kettle-water" x="159" y="143" width="11" height="0" rx="4" fill="#aaa"/><path class="line internals" d="m120 145 8-9 8 9 8-9 8 9 8-9 8 9 8-9 8 9 8-9 8 9"/><g class="kettle-steam"><path class="line" d="M144 58q-8-10 0-20t0-20M165 56q-8-10 0-20t0-20M185 58q-8-10 0-20t0-20"/></g><path class="top" d="M138 76q0-18 26-18t26 18"/><rect x="198" y="148" width="17" height="6" rx="2" fill="#aaa"/><text class="part-label" x="18" y="150">Element</text><path class="part-label line" d="M65 147h50"/><text class="part-label" x="252" y="119">Handle</text>`,
`<button id="kettle-fill">Fill water</button><button class="primary" id="kettle-heat" disabled>Boil</button><button id="kettle-pour" disabled>Pour cup</button>`, 'Add water before switching on.'),
`.kettle-steam{opacity:0}.heating .kettle-steam{opacity:1;animation:figure-steam 1.5s ease-in-out infinite}#kettle-water{transition:y .3s,height .3s}`,
`let water=0,temp=20,heating=false,timer;function render(){document.querySelector('.figure-demo').classList.toggle('heating',heating);document.querySelector('#kettle-fill').disabled=heating||water>=3;document.querySelector('#kettle-heat').disabled=heating||!water||temp>=100;document.querySelector('#kettle-pour').disabled=heating||!water;document.querySelector('#kettle-water').setAttribute('height',water*13);document.querySelector('#kettle-water').setAttribute('y',145-water*13);document.querySelector('#figure-state').textContent=water?(heating?'Heating / ':temp===100?'Boiled / ':'Ready / ')+temp+'°C':'Empty';document.querySelector('#figure-caption').textContent=water?(water+' cups of water. '+(heating?'Heating switches off automatically at 100°C.':'Fill, boil, or pour.')):'Add water before switching on.'}document.querySelector('#kettle-fill').onclick=()=>{water++;temp=20;render()};document.querySelector('#kettle-heat').onclick=()=>{if(!water||heating)return;heating=true;render();timer=setInterval(()=>{temp=Math.min(100,temp+10);if(temp===100){clearInterval(timer);heating=false}render()},300)};document.querySelector('#kettle-pour').onclick=()=>{if(!water||heating)return;water--;temp=water?temp:20;render()};render();`),
make('ref-desk-lamp','Desk lamp','A poseable desk lamp with a real dimmer, power switch, labeled joints, and an inspectable wire path.',
frame('Desk lamp','Off',`<ellipse cx="170" cy="170" rx="57" ry="15" class="shell"/><path class="lamp-beam" d="m183 70 70 99H128z" fill="#ffffff" opacity="0"/><path class="line internals" stroke-dasharray="3 3" d="M170 169V115l-25-30 49-37"/><g class="lamp-arm" style="transform-origin:170px 164px"><path d="M170 164v-47l-32-38 54-37" fill="none" stroke="#555" stroke-width="9" stroke-linejoin="round"/><path d="M170 164v-47l-32-38 54-37" fill="none" stroke="#ddd" stroke-width="2" stroke-linejoin="round"/><circle cx="170" cy="117" r="6" class="shell"/><circle cx="138" cy="79" r="6" class="shell"/><path class="shell" d="m179 41 15-14 41 27-10 20z"/><ellipse class="lamp-bulb" cx="223" cy="64" rx="14" ry="8" fill="#555" stroke="#aaa" transform="rotate(35 223 64)"/></g><text class="part-label" x="44" y="85">Pivot joint</text><path class="part-label line" d="M104 82h25"/><text class="part-label" x="231" y="143">Dimmer</text><circle cx="192" cy="169" r="4" fill="#888"/>`,
`<button class="primary" id="lamp-power" aria-pressed="false">Switch on</button><label>Dim <input id="lamp-dim" type="range" min="10" max="100" value="70" aria-label="Lamp brightness"></label><label>Angle <input id="lamp-angle" type="range" min="-12" max="15" value="0" aria-label="Lamp arm angle"></label>`, 'Switch on, then adjust the light.'),
`.figure-controls label{display:flex;align-items:center;gap:4px;font-size:9px;color:#888}.figure-controls label input{width:57px}.lamp-arm{transition:transform .15s}.lamp-beam,.lamp-bulb{transition:opacity .2s,fill .2s}`,
`let on=false;const power=document.querySelector('#lamp-power'),dim=document.querySelector('#lamp-dim'),angle=document.querySelector('#lamp-angle');function render(){const brightness=Number(dim.value);power.textContent=on?'Switch off':'Switch on';power.setAttribute('aria-pressed',on);document.querySelector('.lamp-beam').setAttribute('opacity',on?brightness/650:0);document.querySelector('.lamp-bulb').setAttribute('fill',on?'#eee':'#555');document.querySelector('.lamp-arm').style.transform='rotate('+angle.value+'deg)';document.querySelector('#figure-state').textContent=on?'On / '+brightness+'%':'Off';document.querySelector('#figure-caption').textContent=on?'Brightness '+brightness+'%. Arm angle '+angle.value+'°.':'Switch on, then adjust the light.'}power.onclick=()=>{on=!on;render()};dim.oninput=angle.oninput=render;render();`),
make('ref-vending-machine','Vending machine','Insert coins, select a product, and vend from a finite stock. Controls follow credit and availability rules.',
frame('Vending machine','No credit',`<path class="side outer-skin" d="m220 44 28-16v145l-28 17z"/><path class="top outer-skin" d="m97 44 28-16h123l-28 16z"/><rect class="shell outer-skin" x="97" y="44" width="123" height="146" rx="4"/><rect x="108" y="56" width="75" height="87" rx="3" fill="#0b0b0b" stroke="#666"/><path class="line internals" stroke-dasharray="3 3" d="M112 78h67m-67 31h67m-58-38 8 7-8 7 8 7-8 7m24-28 8 7-8 7 8 7-8 7m24-28 8 7-8 7 8 7-8 7"/><g class="stock-cans"><rect x="117" y="69" width="13" height="24" rx="3" fill="#ccc"/><rect x="140" y="69" width="13" height="24" rx="3" fill="#999"/><rect x="163" y="69" width="13" height="24" rx="3" fill="#666"/></g><path class="line" d="M111 102h69M111 133h69"/><rect x="194" y="67" width="15" height="8" rx="1" fill="#ddd"/><path class="line" d="M198 90v12m-4 13h13"/><rect x="110" y="154" width="73" height="25" rx="4" fill="#070707" stroke="#777"/><rect class="vended-can" x="140" y="157" width="13" height="20" rx="3" fill="#ccc"/><text class="part-label" x="23" y="87">Products</text><path class="part-label line" d="M76 84h28"/><text class="part-label" x="255" y="97">Coin slot</text>`,
`<button id="vend-coin">Insert coin</button><button id="vend-select">Item A</button><button class="primary" id="vend-buy" disabled>Vend</button><button id="vend-return" disabled>Return</button>`, 'Each item costs one coin.'),
`.vended-can{opacity:0}.dispensed .vended-can{opacity:1;animation:can-drop .65s ease-out}.stock-cans rect{transition:opacity .2s}@keyframes can-drop{from{transform:translateY(-70px);opacity:0}to{transform:translateY(0);opacity:1}}`,
`let credit=0,selection=0,busy=false;const stock=[3,3,3],names=['A','B','C'];function render(){document.querySelector('#vend-buy').disabled=busy||credit<1||stock[selection]<1;document.querySelector('#vend-coin').disabled=busy||credit>=3;document.querySelector('#vend-select').disabled=busy;document.querySelector('#vend-return').disabled=busy||!credit;document.querySelector('#vend-select').textContent='Item '+names[selection];document.querySelector('#figure-state').textContent=busy?'Dispensing':credit+' coin'+(credit===1?'':'s');document.querySelector('#figure-caption').textContent=busy?'The item is moving to the collection tray.':'Item '+names[selection]+': '+stock[selection]+' left. One coin per item.';document.querySelectorAll('.stock-cans rect').forEach((r,i)=>r.style.opacity=stock[i]?1:.15)}document.querySelector('#vend-coin').onclick=()=>{credit=Math.min(3,credit+1);render()};document.querySelector('#vend-select').onclick=()=>{selection=(selection+1)%3;render()};document.querySelector('#vend-return').onclick=()=>{credit=0;render()};document.querySelector('#vend-buy').onclick=()=>{if(busy||!credit||!stock[selection])return;credit--;stock[selection]--;busy=true;const root=document.querySelector('.figure-demo');root.classList.remove('dispensed');void root.offsetWidth;root.classList.add('dispensed');render();setTimeout(()=>{busy=false;render()},800)};render();`),
make('ref-parcel-locker','Parcel locker','Enter the matching collection code to unlock a door, then close it to complete the handoff.',
frame('Parcel locker','Locked',`<path class="side outer-skin" d="m246 46 23-16v143l-23 16z"/><path class="top outer-skin" d="m80 46 23-16h166l-23 16z"/><rect class="shell outer-skin" x="80" y="46" width="166" height="143" rx="3"/>${Array.from({length:6},(_,i)=>{const x=89+(i%3)*51,y=57+Math.floor(i/3)*61;return `<g class="locker-door door-${i}"><rect x="${x}" y="${y}" width="44" height="53" rx="2" fill="#252525" stroke="#888"/><path class="line" d="M${x+34} ${y+24}v9"/><text x="${x+5}" y="${y+13}">${i+1}</text></g>`}).join('')}<g class="internals"><rect x="144" y="127" width="29" height="22" fill="#888" stroke="#ddd"/><path class="line" d="m144 127 14-6 29 1-14 5m0 0 14-5v21l-14 6"/></g><text class="part-label" x="15" y="148">Door 5</text><path class="part-label line" d="M53 145h28"/><text class="part-label" x="275" y="115">Locker</text>`,
`<input id="locker-code" type="text" inputmode="numeric" maxlength="4" aria-label="Collection code" placeholder="Code 1234"><button class="primary" id="locker-open">Unlock</button><button id="locker-close" disabled>Close door</button>`, 'Demo collection code: 1234. Door 5 holds the parcel.'),
`.locker-door{transition:opacity .25s,transform .25s}.locker-unlocked .door-4{opacity:.18;transform:translateX(-18px)}.locker-unlocked .internals{opacity:1}.figure-demo input[aria-invalid=true]{border-color:#ddd;outline:1px dashed #aaa}`,
`let open=false;const code=document.querySelector('#locker-code'),unlock=document.querySelector('#locker-open'),close=document.querySelector('#locker-close');function render(){document.querySelector('.figure-demo').classList.toggle('locker-unlocked',open);document.querySelector('#figure-state').textContent=open?'Door 5 open':'Locked';unlock.disabled=open;close.disabled=!open;code.disabled=open}function submit(){if(open)return;if(code.value!=='1234'){code.setAttribute('aria-invalid','true');document.querySelector('#figure-caption').textContent='Code not recognized. Try 1234.';return}code.removeAttribute('aria-invalid');open=true;document.querySelector('#figure-caption').textContent='Door 5 unlocked. Close it after collecting the parcel.';render()}unlock.onclick=submit;code.onkeydown=e=>{if(e.key==='Enter')submit()};close.onclick=()=>{open=false;code.value='';document.querySelector('#figure-caption').textContent='Door secured. Use code 1234 to try again.';render()};render();`)
];
